import java.time.LocalDate;

/**
 * Blocks dispensing when the selected stock batch has passed its expiry date.
 */
public class ExpiredStockGuard {

    private final StockBatchRepository batches;

    public ExpiredStockGuard(StockBatchRepository batches) {
        this.batches = batches;
    }

    public void assertUsable(String batchId, LocalDate today) {
        StockBatch batch = batches.require(batchId);
        if (batch.getExpiryDate().isBefore(today)) {
            throw new ExpiredBatchException(batchId, batch.getExpiryDate());
        }
    }
}

class ExpiredBatchException extends RuntimeException {
    public ExpiredBatchException(String batchId, LocalDate expiry) {
        super("Batch " + batchId + " expired on " + expiry);
