package com.acme.pharmacy.billing;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

/**
 * Splits the total between insurance coverage and patient payment.
 */
public class DispensingChargeCalculator {

    private final PricingService pricing;
    private final CoveragePolicy coverage;

    public DispensingChargeCalculator(PricingService pricing, CoveragePolicy coverage) {
        this.pricing = pricing;
        this.coverage = coverage;
    }

    public DispenseCharge calculate(List<DispensedItem> items, String schemeCode) {
        BigDecimal retail = items.stream()
            .map(i -> pricing.retailPrice(i.getMedicineCode()).multiply(BigDecimal.valueOf(i.getQuantity())))
            .reduce(BigDecimal.ZERO, BigDecimal::add);
        BigDecimal covered = coverage.coveredPortion(schemeCode, retail);
        BigDecimal payable = retail.subtract(covered).max(BigDecimal.ZERO);
        return new DispenseCharge(retail, covered, payable.setScale(2, RoundingMode.HALF_UP));
    }
}

