package com.acme.pharmacy.prescriptions;

import java.math.BigDecimal;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

/**
 * Records a prescription after checking dose against age band.
 */
@RestController
public class PrescriptionEntryController {

    private final DoseRangeRepository doseRanges;
    private final PrescriptionRepository prescriptions;
    private final PatientRepository patients;

    public PrescriptionEntryController(DoseRangeRepository doseRanges,
                                       PrescriptionRepository prescriptions,
                                       PatientRepository patients) {
        this.doseRanges = doseRanges;
        this.prescriptions = prescriptions;
        this.patients = patients;
    }

    @PostMapping("/prescriptions")
    public PrescriptionView enter(@RequestBody PrescriptionRequest req) {
        Patient p = patients.require(req.getPatientId());
        DoseRange range = doseRanges.forMedicineAndAge(req.getMedicineCode(), p.getAgeInYears());
        BigDecimal dose = req.getDoseMg();
        if (dose.compareTo(range.getMin()) < 0 || dose.compareTo(range.getMax()) > 0) {
            throw new DoseOutOfRangeException(req.getMedicineCode(), dose, range);
        }
        Prescription pr = new Prescription(req.getPatientId(), req.getMedicineCode(), dose, req.getFrequency(), req.getDurationDays(), req.getPrescriberId());
        return PrescriptionView.from(prescriptions.save(pr));
    }
}

