package com.acme.pharmacy.stock;

import java.time.LocalDate;
import java.util.List;

/**
 * Records a wholesaler delivery as batches and updates on-hand stock.
 */
public class DeliveryReceiptService {

    private final StockBatchRepository batches;
    private final MedicineRepository medicines;

    public DeliveryReceiptService(StockBatchRepository batches, MedicineRepository medicines) {
        this.batches = batches;
        this.medicines = medicines;
    }

    public List<StockBatch> receive(String medicineCode, String wholesalerRef, List<BatchLine> lines) {
        Medicine medicine = medicines.require(medicineCode);
        for (BatchLine l : lines) {
            if (l.getExpiryDate().isBefore(LocalDate.now())) {
                throw new IllegalArgumentException("Batch expiring in the past: " + l.getBatchNumber());
            }
        }
        return lines.stream()
            .map(l -> batches.save(new StockBatch(medicine.getCode(), l.getBatchNumber(), l.getQuantity(), l.getExpiryDate(), wholesalerRef)))
            .toList();
    }
}

