    public void assertValid(Prescription p, LocalDate today) {
        long age = ChronoUnit.DAYS.between(p.getIssuedOn(), today);
        if (age > VALID_DAYS) {
            throw new PrescriptionExpiredException(p.getId(), age);
        }
    }
}

