package com.acme.pharmacy.audit;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Persists an immutable dispensing event for recall and audit purposes.
 */
public class DispensingEventRecorder {

    private final EntityManager em;

    public DispensingEventRecorder(EntityManager em) {
        this.em = em;
    }

    public void record(String patientId, String medicineCode, String batchId, int quantity, String pharmacistId, String prescriptionId) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            DispensingEvent e = new DispensingEvent();
            e.setPatientId(patientId);
            e.setMedicineCode(medicineCode);
            e.setBatchId(batchId);
            e.setQuantity(quantity);
            e.setPharmacistId(pharmacistId);
            e.setPrescriptionId(prescriptionId);
            e.setDispensedAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

