/* expiry_report.c - write batches expiring within 30 days as CSV */
#include <stdio.h>
#include "pharmacy_db.h"

int write_expiry_report(const char *today, const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    fprintf(out, "medicine_code,batch_number,expiry_date,on_hand,location\n");

    db_cursor_t *cur = NULL;
    if (db_open_expiring_batches_cursor(&cur, today, 30) != DB_OK) { fclose(out); return -2; }

    int rows = 0;
    batch_row_t row;
    while (db_batch_cursor_next(cur, &row) == DB_OK) {
        if (row.on_hand <= 0) continue;
        if (row.recalled) continue;
        fprintf(out, "%s,%s,%s,%d,%s\n",
                row.medicine_code, row.batch_number, row.expiry_date,
                row.on_hand, row.location_id);
        rows++;
    }
    db_close_cursor(cur);
    fclose(out);
    return rows;
}

